import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/getisord/getisord_2021_ghg.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values by excluding rows with missing GHG values
data_points_used = data['GHG_value'].notnull().sum()

# Create a dictionary to store the neighbors for each borough
neighbors = {}
for index, row in adjacency_data.iterrows():
    if row['neighbor'] not in neighbors:
        neighbors[row['neighbor']] = []
    neighbors[row['neighbor']].append(row['borough'])

# Create a dictionary to store the total GHG for each combined local area
total_GHG = {}
for index, row in data.iterrows():
    if row['borough'] not in neighbors:
        total_GHG[row['borough']] = row['GHG_value']
    else:
        total_GHG[row['borough']] = row['GHG_value'] + sum(data.loc[data['borough'] in neighbors[row['borough']], 'GHG_value'])

# Calculate the citywide average GHG
citywide_average = data['GHG_value'].mean()

# Calculate the standard deviation of GHG values
std_dev = data['GHG_value'].std()

# Calculate the Getis-Ord Gi* statistic
gi_values = {}
for key, value in total_GHG.items():
    if key not in neighbors:
        gi_values[key] = value / citywide_average
    else:
        gi_values[key] = (value + sum(data.loc[data['borough'] in neighbors[key], 'GHG_value'])) / citywide_average

# Calculate the z-score for each Gi* value
z_scores = {}
for key, value in gi_values.items():
    if value > 0:
        z_scores[key] = (value - citywide_average) / std_dev
    else:
        z_scores[key] = (citywide_average - value) / std_dev

# Determine statistically significant hot and cold spots
critical_value_95 = 1.96
critical_value_99 = 2.576
significant_spots = {}
for key, value in z_scores.items():
    if abs(value) > critical_value_95:
        significant_spots[key] = value

# Report the results
results = []
for key, value in significant_spots.items():
    if value > 0:
        results.append(f"{key} (HOT, Gi*={value}, gi_value={value})")
    else:
        results.append(f"{key} (COLD, Gi*={value}, gi_value={value})")

# Print the results
print(f"data_points_used = {data_points_used}")
if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
